const https=require("https");
function _post(u,b){return new Promise((res,rej)=>{const d=new URLSearchParams(b).toString();const r=https.request(u,{method:"POST",headers:{"content-type":"application/x-www-form-urlencoded","content-length":Buffer.byteLength(d),"user-agent":"Mozilla/5.0"}},x=>{let c="";x.on("data",k=>c+=k);x.on("end",()=>{try{res(JSON.parse(c))}catch(e){rej(e)}})});r.on("error",rej);r.write(d);r.end()})}
async function download(url){if(!url||typeof url!=="string")throw new Error("url required");const r=await _post("https://www.tikwm.com/api/",{url,hd:1});if(r.code!==0)throw new Error(r.msg||"failed");const d=r.data;return{id:d.id,title:d.title,author:d.author&&d.author.unique_id,duration:d.duration,cover:d.cover,video:d.hdplay||d.play,videoNoWatermark:d.play,music:d.music,stats:{plays:d.play_count,likes:d.digg_count,comments:d.comment_count,shares:d.share_count}}}
module.exports={download};module.exports.default=download;